# UNESCO World Heritage Sites API
import requests

UNESCO_API_KEY = "profaddic7edadhearsionabscssadmin"
BASE_URL = "https://whc.unesco.org/api"

def list_world_heritage_sites(country=None, category=None):
    """List World Heritage sites by criteria"""
    params = {
        "apikey": UNESCO_API_KEY,
        "format": "json"
    }
    if country:
        params["country"] = country
    if category:
        params["category"] = category

    response = requests.get(f"{BASE_URL}/sites", params=params)
    return response.json()

def get_site_details(site_id):
    """Get detailed information about a World Heritage site"""
    response = requests.get(
        f"{BASE_URL}/sites/{site_id}",
        params={"apikey": UNESCO_API_KEY, "format": "json"}
    )
    return response.json()

def get_sites_in_danger():
    """Get list of World Heritage sites in danger"""
    response = requests.get(
        f"{BASE_URL}/danger",
        params={"apikey": UNESCO_API_KEY, "format": "json"}
    )
    return response.json()
